"""Max-pool2d-with-indices backward, Triton implementation.

The backward is a pure scatter-add of grad_output through the forward's argmax
map: grad_input[plane*HW + idx[k]] += grad_output[k].

One deterministic inverse-gather kernel serves every dtype: each grad_input
element is written exactly once by the program that owns it, contributions are
accumulated in fp32 registers and rounded once on store.  That matches the
reference's fp32-accumulating ascending (kh, kw) order bit-for-bit, which the
pytest's 1-ULP-level fp16/bf16 tolerances require (reduced-precision atomics
round once per contribution and fail wherever two windows collide), and it
avoids both the extra launch and the full-tensor zeros/fp32 pass of the
reference.

The gather enumerates only output positions that can actually select a pixel:
for input coordinate i the candidates are oh = (i + P)//S - j with
t = (i + P) - oh*S = rem + j*S for j in [0, (K-1)*D//S].  j ascends with kh, so
the accumulation order is the reference's.

The kernel is integer issue bound, so each element forms its top-left tap offset
once (t_base = base + base_oh*stride_h + base_ow*stride_w) and every tap is that
offset minus the compile-time (contiguous) or scalar delta
jh*stride_h + jw*stride_w; the index compare stays 32-bit and the index and grad
loads of a tap share one offset when both tensors have the same strides.  A
fixed BLOCK/num_warps pair is used because the profiled launch-shape sweep was a
flat optimum and the autotuner's per-call key lookup costs ~1 us.
"""

import torch
import triton
import triton.language as tl

BLOCK = 512
NUM_WARPS = 4


@triton.jit
def _gather_kernel(
    go_ptr,  # grad_output  (N, C, OH, OW) or (C, OH, OW)
    ix_ptr,  # indices      same shape, in-plane flat offsets
    gi_ptr,  # grad_input   (N, C, H, W) or (C, H, W), fully overwritten
    go_sn,
    go_sc,
    go_sh,
    go_sw,
    ix_sn,
    ix_sc,
    ix_sh,
    ix_sw,
    C,
    TOTAL_IN,
    HW: tl.constexpr,
    W: tl.constexpr,
    OH: tl.constexpr,
    OW: tl.constexpr,
    SH: tl.constexpr,
    SW: tl.constexpr,
    PH: tl.constexpr,
    PW: tl.constexpr,
    DH: tl.constexpr,
    DW: tl.constexpr,
    NCH: tl.constexpr,
    NCW: tl.constexpr,
    TMAXH: tl.constexpr,
    TMAXW: tl.constexpr,
    FLAT: tl.constexpr,
    SHARED: tl.constexpr,
    BLOCK: tl.constexpr,
):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    m = offs < TOTAL_IN
    plane = offs // HW
    p = offs - plane * HW
    h = p // W
    w = p - h * W

    nh = h + PH
    nw = w + PW
    base_oh = nh // SH
    rem_h = nh - base_oh * SH
    base_ow = nw // SW
    rem_w = nw - base_ow * SW

    if FLAT:
        # Contiguous grad_output/indices: flat offsets coincide and both plane
        # bases and stride deltas are compile-time constants.
        t_base = plane * (OH * OW) + base_oh * OW + base_ow
    elif SHARED:
        n = plane // C
        c = plane - n * C
        base = n * go_sn + c * go_sc
        t_base = base + base_oh * go_sh + base_ow * go_sw
    else:
        n = plane // C
        c = plane - n * C
        go_t = n * go_sn + c * go_sc + base_oh * go_sh + base_ow * go_sw
        ix_t = n * ix_sn + c * ix_sc + base_oh * ix_sh + base_ow * ix_sw

    acc = tl.zeros((BLOCK,), dtype=tl.float32)
    for jh in tl.static_range(NCH):
        th = rem_h + jh * SH
        oh = base_oh - jh
        ok_h = (th <= TMAXH) & (oh >= 0) & (oh < OH)
        if DH > 1:
            ok_h = ok_h & (th % DH == 0)
        for jw in tl.static_range(NCW):
            tw = rem_w + jw * SW
            ow = base_ow - jw
            ok_w = (tw <= TMAXW) & (ow >= 0) & (ow < OW)
            if DW > 1:
                ok_w = ok_w & (tw % DW == 0)
            tap = m & ok_h & ok_w
            if FLAT:
                t_off = t_base - (jh * OW + jw)
                sel = tl.load(ix_ptr + t_off, mask=tap, other=-1)
                hit = tap & (sel.to(tl.int32) == p)
                val = tl.load(go_ptr + t_off, mask=hit, other=0.0)
            elif SHARED:
                t_off = t_base - (jh * go_sh + jw * go_sw)
                sel = tl.load(ix_ptr + t_off, mask=tap, other=-1)
                hit = tap & (sel.to(tl.int32) == p)
                val = tl.load(go_ptr + t_off, mask=hit, other=0.0)
            else:
                sel = tl.load(
                    ix_ptr + (ix_t - (jh * ix_sh + jw * ix_sw)), mask=tap, other=-1
                )
                hit = tap & (sel.to(tl.int32) == p)
                val = tl.load(
                    go_ptr + (go_t - (jh * go_sh + jw * go_sw)), mask=hit, other=0.0
                )
            acc += val.to(tl.float32)

    tl.store(gi_ptr + offs, acc.to(gi_ptr.dtype.element_ty), mask=m)


def _pair(v, default):
    if v is None:
        return default
    if isinstance(v, (list, tuple)):
        if len(v) == 0:
            return default
        if len(v) == 1:
            a = int(v[0])
            return (a, a)
        return (int(v[0]), int(v[1]))
    a = int(v)
    return (a, a)


def max_pool2d_with_indices_backward(
    grad_output,
    self,
    kernel_size,
    stride=None,
    padding=0,
    dilation=1,
    ceil_mode=False,
    indices=None,
    **kwargs,
):
    if indices is None:
        indices = kwargs["indices"]

    kernel_h, kernel_w = _pair(kernel_size, None)
    stride_h, stride_w = _pair(stride, (kernel_h, kernel_w))
    pad_h, pad_w = _pair(padding, (0, 0))
    dil_h, dil_w = _pair(dilation, (1, 1))

    if self.dim() == 3:
        n, c, h, w = 1, int(self.shape[0]), int(self.shape[1]), int(self.shape[2])
        go_sn = 0
        ix_sn = 0
    else:
        n, c, h, w = (int(s) for s in self.shape)
        go_sn = int(grad_output.stride(0))
        ix_sn = int(indices.stride(0))

    oh = int(grad_output.shape[-2])
    ow = int(grad_output.shape[-1])

    if oh == 0 or ow == 0:
        return torch.zeros(self.shape, dtype=grad_output.dtype, device=self.device)
    gi = torch.empty(self.shape, dtype=grad_output.dtype, device=self.device)
    if gi.numel() == 0:
        return gi

    go_strides = (
        go_sn,
        int(grad_output.stride(-3)),
        int(grad_output.stride(-2)),
        int(grad_output.stride(-1)),
    )
    ix_strides = (
        ix_sn,
        int(indices.stride(-3)),
        int(indices.stride(-2)),
        int(indices.stride(-1)),
    )

    total_in = n * c * h * w
    _gather_kernel[(triton.cdiv(total_in, BLOCK),)](
        grad_output,
        indices,
        gi,
        *go_strides,
        *ix_strides,
        c,
        total_in,
        HW=h * w,
        W=w,
        OH=oh,
        OW=ow,
        SH=stride_h,
        SW=stride_w,
        PH=pad_h,
        PW=pad_w,
        DH=dil_h,
        DW=dil_w,
        NCH=((kernel_h - 1) * dil_h) // stride_h + 1,
        NCW=((kernel_w - 1) * dil_w) // stride_w + 1,
        TMAXH=(kernel_h - 1) * dil_h,
        TMAXW=(kernel_w - 1) * dil_w,
        FLAT=grad_output.is_contiguous() and indices.is_contiguous(),
        SHARED=go_strides == ix_strides,
        BLOCK=BLOCK,
        num_warps=NUM_WARPS,
    )
    return gi
